const OPERATIONS = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b,
};

const TOOL_SCHEMA = {
  name: 'calculate',
  description: 'Perform a basic arithmetic calculation on two numbers.',
  inputSchema: {
    type: 'object',
    properties: {
      a: { type: 'number', description: 'The first operand.' },
      b: { type: 'number', description: 'The second operand.' },
      operation: {
        type: 'string',
        enum: ['add', 'subtract', 'multiply', 'divide'],
        description: 'The arithmetic operation to perform.',
      },
    },
    required: ['a', 'b', 'operation'],
    additionalProperties: false,
  },
};

function isNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function validateArgs(args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object.');
  }

  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Invalid argument: '${key}' is not allowed.`);
    }
  }

  for (const key of ['a', 'b', 'operation']) {
    if (!(key in args)) {
      throw new Error(`Missing required argument: '${key}'.`);
    }
  }

  if (!isNumber(args.a)) {
    throw new Error("Invalid argument 'a': expected a finite number.");
  }
  if (!isNumber(args.b)) {
    throw new Error("Invalid argument 'b': expected a finite number.");
  }
  if (typeof args.operation !== 'string' || !(args.operation in OPERATIONS)) {
    throw new Error(`Unsupported operation: '${args.operation}'.`);
  }
}

export async function listTools() {
  return [TOOL_SCHEMA];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: '${name}'.`);
  }

  validateArgs(args || {});

  const { a, b, operation } = args;

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero is not allowed.');
  }

  const result = OPERATIONS[operation](a, b);

  return {
    content: [{ type: 'text', text: `${result}` }],
  };
}

